def list_tools(**_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0406000" if __import__("os").path.isdir("./environment_mix/0406000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _utc_day(dt):
        return dt.astimezone(datetime.timezone.utc).date()

    def _gen_req_id():
        return "req_" + hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:24]

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _find_any_active_key(keys):
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _reset_daily_if_needed(key_row, now_dt):
        # Enforce: reset requests_today at UTC day boundary
        last_reset = _parse_iso(key_row.get("requests_today_reset_at"))
        if last_reset is None:
            # repair/reset timestamp; do not decrease counter unless day change
            key_row["requests_today_reset_at"] = _now_iso()
            return
        if _utc_day(last_reset) != _utc_day(now_dt):
            key_row["requests_today"] = 0
            key_row["requests_today_reset_at"] = _now_iso()

    def _count_recent_minute(logs, key_id, now_dt):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            ts = _parse_iso(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                c += 1
        return c

    # Start request
    start = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    req_id = _gen_req_id()
    endpoint = "list_tools"

    api_keys = _load("api_keys.json")
    reqlog_file = _ensure_request_logs()
    req_logs = _load(reqlog_file)

    # Ambient auth: pick any active key that can serve this call (must be active and under limits)
    chosen = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        # Validate limits shape minimally
        try:
            rpm = int(k.get("requests_per_minute_limit"))
            rpd = int(k.get("requests_per_day_limit"))
            rt = int(k.get("requests_today"))
        except Exception:
            continue
        if rpm < 1 or rpd < 1 or rt < 0:
            continue
        _reset_daily_if_needed(k, now_dt)
        # Check quota using stored counter
        if int(k.get("requests_today", 0)) >= rpd:
            continue
        # Check minute rate using request logs
        used_last_min = _count_recent_minute(req_logs, k.get("id"), now_dt)
        if used_last_min >= rpm:
            continue
        chosen = k
        break

    if chosen is None:
        # If there exists a key but all blocked by limits, return RATE_LIMIT or QUOTA_EXCEEDED.
        # Prefer quota if all active keys are quota exceeded, else rate_limit.
        any_active = _find_any_active_key(api_keys)
        status = "error"
        if any_active is None:
            # Still log unauth attempt without key
            latency_ms = int((time.time() - start) * 1000)
            req_logs.append({
                "id": req_id,
                "endpoint": endpoint,
                "api_key_id": None,
                "api_key_prefix": None,
                "status": "UNAUTHORIZED",
                "timestamp": _now_iso(),
                "latency_ms": latency_ms
            })
            _save(reqlog_file, req_logs)
            return _err("UNAUTHORIZED", "No active API key available for ambient authentication.")

        # Determine whether quota or rate limit is the blocker for all active keys
        quota_blocked = True
        rate_blocked = True
        for k in api_keys:
            if not isinstance(k, dict) or k.get("status") != "active":
                continue
            _reset_daily_if_needed(k, now_dt)
            try:
                rpm = int(k.get("requests_per_minute_limit"))
                rpd = int(k.get("requests_per_day_limit"))
                rt = int(k.get("requests_today"))
            except Exception:
                continue
            if rt < rpd:
                quota_blocked = False
            used_last_min = _count_recent_minute(req_logs, k.get("id"), now_dt)
            if used_last_min < rpm:
                rate_blocked = False

        code = "QUOTA_EXCEEDED" if quota_blocked else "RATE_LIMIT"
        latency_ms = int((time.time() - start) * 1000)
        req_logs.append({
            "id": req_id,
            "endpoint": endpoint,
            "api_key_id": any_active.get("id") if isinstance(any_active, dict) else None,
            "api_key_prefix": any_active.get("key_prefix") if isinstance(any_active, dict) else None,
            "status": code,
            "timestamp": _now_iso(),
            "latency_ms": latency_ms
        })
        _save(reqlog_file, req_logs)
        _save("api_keys.json", api_keys)
        if code == "QUOTA_EXCEEDED":
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Count this request
    chosen["requests_today"] = int(chosen.get("requests_today", 0)) + 1
    chosen["last_used_at"] = _now_iso()
    chosen["updated_at"] = _now_iso()

    latency_ms = int((time.time() - start) * 1000)
    req_logs.append({
        "id": req_id,
        "endpoint": endpoint,
        "api_key_id": chosen.get("id"),
        "api_key_prefix": chosen.get("key_prefix"),
        "status": "OK",
        "timestamp": _now_iso(),
        "latency_ms": latency_ms
    })
    _save(reqlog_file, req_logs)
    _save("api_keys.json", api_keys)

    tools = [
        {"name": "list_tools", "description": "Returns the list of available API tools/endpoints supported by this service."},
        {"name": "get_restaurants", "description": "Searches for restaurants matching a term and logs the search query; returns only active restaurants."},
        {"name": "get_identity", "description": "Returns the authenticated caller identity derived from the presented API key."},
        {"name": "list_restaurants", "description": "Lists restaurants with optional filtering and pagination."},
    ]
    return {
        "tools": tools,
        "meta": {
            "request_id": req_id,
            "timestamp": _now_iso()
        }
    }

def get_identity(api_key, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0406000" if __import__("os").path.isdir("./environment_mix/0406000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _utc_day(dt):
        return dt.astimezone(datetime.timezone.utc).date()

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _gen_req_id():
        return "req_" + hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:24]

    def _reset_daily_if_needed(key_row, now_dt):
        last_reset = _parse_iso(key_row.get("requests_today_reset_at"))
        if last_reset is None:
            key_row["requests_today_reset_at"] = _now_iso()
            return
        if _utc_day(last_reset) != _utc_day(now_dt):
            key_row["requests_today"] = 0
            key_row["requests_today_reset_at"] = _now_iso()

    def _count_recent_minute(logs, key_id, now_dt):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != key_id:
                continue
            ts = _parse_iso(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                c += 1
        return c

    def _resolve_key(api_key_param, api_keys):
        # Authenticate by matching client-visible value: id or key_prefix (raw secret not available), never key_hash.
        if not isinstance(api_key_param, str) or api_key_param.strip() == "":
            return None
        v = api_key_param.strip()
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if v == k.get("id"):
                return k
            if v == k.get("key_prefix"):
                return k
        return None

    start = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    endpoint = "get_identity"
    req_id = _gen_req_id()

    # Validate input type
    if api_key is None or not isinstance(api_key, str) or api_key.strip() == "":
        reqlog_file = _ensure_request_logs()
        req_logs = _load(reqlog_file)
        latency_ms = int((time.time() - start) * 1000)
        req_logs.append({
            "id": req_id,
            "endpoint": endpoint,
            "api_key_id": None,
            "api_key_prefix": None,
            "status": "UNAUTHORIZED",
            "timestamp": _now_iso(),
            "latency_ms": latency_ms
        })
        _save(reqlog_file, req_logs)
        return _err("UNAUTHORIZED", "API key is missing or invalid.")

    api_keys = _load("api_keys.json")
    reqlog_file = _ensure_request_logs()
    req_logs = _load(reqlog_file)

    key_row = _resolve_key(api_key, api_keys)
    if key_row is None:
        latency_ms = int((time.time() - start) * 1000)
        req_logs.append({
            "id": req_id,
            "endpoint": endpoint,
            "api_key_id": None,
            "api_key_prefix": None,
            "status": "UNAUTHORIZED",
            "timestamp": _now_iso(),
            "latency_ms": latency_ms
        })
        _save(reqlog_file, req_logs)
        return _err("UNAUTHORIZED", "API key is missing or invalid.")

    # Reject non-active
    if key_row.get("status") != "active":
        latency_ms = int((time.time() - start) * 1000)
        req_logs.append({
            "id": req_id,
            "endpoint": endpoint,
            "api_key_id": key_row.get("id"),
            "api_key_prefix": key_row.get("key_prefix"),
            "status": "UNAUTHORIZED",
            "timestamp": _now_iso(),
            "latency_ms": latency_ms
        })
        _save(reqlog_file, req_logs)
        return _err("UNAUTHORIZED", "API key is not active.", key_status=key_row.get("status"))

    # Enforce limits (identity access also counts)
    _reset_daily_if_needed(key_row, now_dt)

    try:
        rpm = int(key_row.get("requests_per_minute_limit"))
        rpd = int(key_row.get("requests_per_day_limit"))
        rt = int(key_row.get("requests_today"))
    except Exception:
        latency_ms = int((time.time() - start) * 1000)
        req_logs.append({
            "id": req_id,
            "endpoint": endpoint,
            "api_key_id": key_row.get("id"),
            "api_key_prefix": key_row.get("key_prefix"),
            "status": "VALIDATION_ERROR",
            "timestamp": _now_iso(),
            "latency_ms": latency_ms
        })
        _save(reqlog_file, req_logs)
        return _err("VALIDATION_ERROR", "API key limits/counters are invalid.")

    if rt >= rpd:
        latency_ms = int((time.time() - start) * 1000)
        req_logs.append({
            "id": req_id,
            "endpoint": endpoint,
            "api_key_id": key_row.get("id"),
            "api_key_prefix": key_row.get("key_prefix"),
            "status": "QUOTA_EXCEEDED",
            "timestamp": _now_iso(),
            "latency_ms": latency_ms
        })
        _save(reqlog_file, req_logs)
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    used_last_min = _count_recent_minute(req_logs, key_row.get("id"), now_dt)
    if used_last_min >= rpm:
        latency_ms = int((time.time() - start) * 1000)
        req_logs.append({
            "id": req_id,
            "endpoint": endpoint,
            "api_key_id": key_row.get("id"),
            "api_key_prefix": key_row.get("key_prefix"),
            "status": "RATE_LIMIT",
            "timestamp": _now_iso(),
            "latency_ms": latency_ms
        })
        _save(reqlog_file, req_logs)
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Count request
    key_row["requests_today"] = int(key_row.get("requests_today", 0)) + 1
    key_row["last_used_at"] = _now_iso()
    key_row["updated_at"] = _now_iso()
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - start) * 1000)
    req_logs.append({
        "id": req_id,
        "endpoint": endpoint,
        "api_key_id": key_row.get("id"),
        "api_key_prefix": key_row.get("key_prefix"),
        "status": "OK",
        "timestamp": _now_iso(),
        "latency_ms": latency_ms
    })
    _save(reqlog_file, req_logs)

    return {
        "identity": {
            "api_key_id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "owner_name": key_row.get("owner_name"),
            "status": key_row.get("status"),
            "scopes": ["restaurants:read", "tools:read", "identity:read"],
            "usage": {
                "requests_per_minute_limit": rpm,
                "requests_per_day_limit": rpd,
                "requests_today": int(key_row.get("requests_today", 0)),
                "requests_today_reset_at": key_row.get("requests_today_reset_at")
            },
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at")
        },
        "meta": {"request_id": req_id, "timestamp": _now_iso()}
    }

