    def _reset_daily_if_needed(key_row, now_dt):
        last_reset = _parse_iso(key_row.get("requests_today_reset_at"))
        if last_reset is None:
            key_row["requests_today_reset_at"] = _now_iso()
            return
        if _utc_day(last_reset) != _utc_day(now_dt):
            key_row["requests_today"] = 0
            key_row["requests_today_reset_at"] = _now_iso()

    def _count_recent_minute(logs, key_id, now_dt):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != key_id:
                continue
            ts = _parse_iso(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                c += 1
        return c

    def _resolve_key(api_key_param, api_keys):
        if not isinstance(api_key_param, str) or api_key_param.strip() == "":
            return None
        v = api_key_param.strip()
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if v == k.get("id") or v == k.get("key_prefix"):
                return k
        return None

    start = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    endpoint = "list_restaurants"
    req_id = _gen_req_id()

    # Validate pagination/sort inputs
    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if sort_by is None:
        sort_by = "updated_at"
    if sort_order is None:
        sort_order = "desc"

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")
