        req_logs.append({
            "id": req_id,
            "endpoint": endpoint,
            "api_key_id": key_row.get("id"),
            "api_key_prefix": key_row.get("key_prefix"),
            "status": "QUOTA_EXCEEDED",
            "timestamp": _now_iso(),
            "latency_ms": latency_ms
        })
        _save(reqlog_file, req_logs)
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    used_last_min = _count_recent_minute(req_logs, key_row.get("id"), now_dt)
    if used_last_min >= rpm:
        latency_ms = int((time.time() - start) * 1000)
        req_logs.append({
            "id": req_id,
            "endpoint": endpoint,
            "api_key_id": key_row.get("id"),
            "api_key_prefix": key_row.get("key_prefix"),
            "status": "RATE_LIMIT",
            "timestamp": _now_iso(),
            "latency_ms": latency_ms
        })
        _save(reqlog_file, req_logs)
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Count request
    key_row["requests_today"] = int(key_row.get("requests_today", 0)) + 1
    key_row["last_used_at"] = _now_iso()
    key_row["updated_at"] = _now_iso()
    _save("api_keys.json", api_keys)

    restaurants = _load("restaurants.json")

    def _ci_eq(a, b):
        if a is None or b is None:
            return False
        if not isinstance(a, str) or not isinstance(b, str):
            return False
        return a.strip().lower() == b.strip().lower()

    filtered = []
    for r in restaurants:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if city is not None and not _ci_eq(r.get("city"), city):
            continue
        if state is not None and not _ci_eq(r.get("state"), state):
            continue
        if country is not None and not _ci_eq(r.get("country"), country):
            continue
        if cuisine is not None and not _ci_eq(r.get("cuisine"), cuisine):
            continue
        if external_provider is not None and not _ci_eq(r.get("external_provider"), external_provider):
            continue
        if external_id is not None and not _ci_eq(r.get("external_id"), external_id):
            continue
        if tag is not None:
            tags = r.get("tags")
