def create_restaurant(api_key, external_provider, external_id, name, city, state, country, latitude, longitude, cuisine=None, tags=None, price_level=None, rating_avg=None, rating_count=None, status=None, **_extra):
    import json, os, datetime, time, unicodedata, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0406000" if __import__("os").path.isdir("./environment_mix/0406000") else "/app/database")
    def _load(n):
