            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return now.isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1]
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _utc_day_start(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _reset_daily_if_needed(k):
        reset_at = _parse_dt(k.get("requests_today_reset_at"))
        start = _utc_day_start(now)
        if reset_at is None or reset_at < start:
            k["requests_today"] = 0
            k["requests_today_reset_at"] = start.isoformat() + "Z"
            return True
        return False

    def _resolve_api_key(raw):
        if not isinstance(raw, str) or not raw.strip():
            return None, None
        raw = raw.strip()
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("id") == raw or k.get("key_prefix") == raw:
                return k, keys
        return None, keys

    def _count_last_minute_requests(key_id):
        queries = _load("search_queries.json")
        cutoff = now - datetime.timedelta(seconds=60)
        n = 0
        for q in queries:
            if q.get("api_key_id") != key_id:
                continue
            dt = _parse_dt(q.get("created_at"))
            if dt is not None and dt >= cutoff:
                n += 1
        return n

    def _record_usage(keys_all, key_row, status):
        mutated = False
        if key_row is not None:
            if _reset_daily_if_needed(key_row):
                mutated = True
            if status == "ok":
                key_row["requests_today"] = int(key_row.get("requests_today") or 0) + 1
                key_row["last_used_at"] = _now_iso()
                mutated = True
            key_row["updated_at"] = _now_iso()
            mutated = True
        if mutated and keys_all is not None:
            _save("api_keys.json", keys_all)

    def _normalize_name(s):
        s = s.strip().lower()
        s = "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c))
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _gen_id(prefix, existing_ids):
        # time-sortable-ish id
        base = int(time.time() * 1000)
        i = 0
        while True:
            cand = f"{prefix}{base:x}{i:x}"
            if cand not in existing_ids:
                return cand
            i += 1

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(external_provider, str) or not external_provider.strip():
        return _err("VALIDATION_ERROR", "external_provider must be a non-empty string.")
    if external_provider not in ("ifood", "other"):
        # restaurants.external_provider is nullable in schema, but tool requires a string; enforce enum if provided
        return _err("VALIDATION_ERROR", "external_provider must be one of: ifood, other.", allowed=["ifood", "other"])
    if not isinstance(external_id, str) or not external_id.strip():
        return _err("VALIDATION_ERROR", "external_id must be a non-empty string.")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if not isinstance(city, str) or not city.strip():
