    if country != "BR":
        return _err("VALIDATION_ERROR", "country must be 'BR'.", allowed=["BR"])
    if not isinstance(latitude, (int, float)) or latitude < -90 or latitude > 90:
        return _err("VALIDATION_ERROR", "latitude must be a number between -90 and 90.")
    if not isinstance(longitude, (int, float)) or longitude < -180 or longitude > 180:
        return _err("VALIDATION_ERROR", "longitude must be a number between -180 and 180.")

    if tags is None:
        tags = []
    if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
        return _err("VALIDATION_ERROR", "tags must be an array of strings.")
    if cuisine is not None and (not isinstance(cuisine, str)):
        return _err("VALIDATION_ERROR", "cuisine must be a string when provided.")
    if price_level is not None:
        if not isinstance(price_level, int) or price_level < 1 or price_level > 4:
            return _err("VALIDATION_ERROR", "price_level must be an integer between 1 and 4.")
    if rating_avg is not None:
        if not isinstance(rating_avg, (int, float)) or rating_avg < 0 or rating_avg > 5:
            return _err("VALIDATION_ERROR", "rating_avg must be a number between 0 and 5.")
    if rating_count is not None:
        if not isinstance(rating_count, int) or rating_count < 0:
            return _err("VALIDATION_ERROR", "rating_count must be an integer >= 0.")
    if status is None:
        status = "active"
    if status not in ("active", "temporarily_unavailable", "closed"):
        return _err("VALIDATION_ERROR", "status must be one of: active, temporarily_unavailable, closed.")

