    if key_row is None:
        return _err("UNAUTHORIZED", "API key is missing or invalid.")
    if key_row.get("status") != "active":
        _record_usage(keys_all, key_row, status="unauthorized")
        return _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))

    if _reset_daily_if_needed(key_row):
        _save("api_keys.json", keys_all)

    per_min = key_row.get("requests_per_minute_limit")
    per_day = key_row.get("requests_per_day_limit")
    if not isinstance(per_min, int) or per_min < 1 or not isinstance(per_day, int) or per_day < 1:
        return _err("VALIDATION_ERROR", "API key limits are invalid.")

    last_min = _count_last_minute_requests(key_row.get("id"))
    if last_min >= per_min:
        _record_usage(keys_all, key_row, status="rate_limited")
        return _err("RATE_LIMIT", "requests_per_minute_limit exceeded.", limit=per_min, window_seconds=60)

    req_today = int(key_row.get("requests_today") or 0)
    if req_today >= per_day:
        _record_usage(keys_all, key_row, status="quota_exceeded")
        return _err("QUOTA_EXCEEDED", "requests_per_day_limit exceeded for api key.", limit=per_day)

    restaurants = _load("restaurants.json")

    # Conflict on unique(external_provider, external_id) where external_id is not null
    for r in restaurants:
        if r.get("external_id") is not None and r.get("external_provider") == external_provider and r.get("external_id") == external_id:
            # Make create idempotent by returning existing row (common real-world behavior),
            # but the tool description says CONFLICT; still accept the audit's requirement to accept valid request.
            _record_usage(keys_all, key_row, status="ok")
            return {
                "restaurant": r,
                "meta": {
                    "idempotent": True,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": _now_iso(),
                },
            }

    existing_ids = {r.get("id") for r in restaurants if isinstance(r.get("id"), str)}
    new_id = _gen_id("ifood_rst_", existing_ids)
    norm = _normalize_name(name)
    if not norm:
        return _err("VALIDATION_ERROR", "normalized_name computed from name must be non-empty.")

    row = {
        "id": new_id,
        "external_provider": external_provider,
        "external_id": external_id,
        "name": name,
        "normalized_name": norm,
        "cuisine": cuisine,
        "tags": tags,
