        "rating_count": int(rating_count) if rating_count is not None else 0,
        "status": status,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }

    restaurants.append(row)
    _save("restaurants.json", restaurants)
    _record_usage(keys_all, key_row, status="ok")

    return {
        "restaurant": row,
        "meta": {
            "created": True,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        },
    }

