            _save("api_keys.json", keys)
        return _err("QUOTA_EXCEEDED", "requests_per_day_limit exceeded for API key.", limit=per_day_limit)

    # Count this request and persist key
    k["requests_today"] = int(k.get("requests_today", 0)) + 1
    k["last_used_at"] = _now_iso()
    k["updated_at"] = _now_iso()
    _save("api_keys.json", keys)

    # Find restaurant; IMPORTANT: do not assume restaurant ids have a prefix; accept any string id.
    restaurants = _load("restaurants.json")
    rid = id.strip()
    idx = None
    for i, r in enumerate(restaurants):
        if r.get("id") == rid:
            idx = i
            break
    if idx is None:
        # Record as audit in search_queries (no dedicated request log)
        queries = _load("search_queries.json")
        latency_ms = int((time.time() - t0) * 1000)
        qry_id = "ifood_qry_" + now.strftime("%Y%m%d%H%M%S") + "_" + str(int(time.time() * 1000))[-6:]
        queries.append({
            "id": qry_id,
            "api_key_id": k.get("id"),
            "term": "__update_restaurant__:" + rid,
            "normalized_term": "__update_restaurant__:" + rid.lower(),
            "status": "failed",
            "result_count": 0,
            "error_code": "not_found",
            "error_message": "Restaurant not found.",
            "client_ip": None,
            "user_agent": None,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
            "endpoint": "update_restaurant",
            "latency_ms": latency_ms,
        })
        _save("search_queries.json", queries)
        return _err("NOT_FOUND", "Restaurant not found.", id=rid)

    r = restaurants[idx]

    # Enforce lifecycle transition if status is changing
    if status is not None and status != r.get("status"):
        transitions = {
            "active": ["temporarily_unavailable", "closed"],
            "temporarily_unavailable": ["active", "closed"],
            "closed": []
        }
        cur = r.get("status")
        allowed = transitions.get(cur, [])
        if status not in allowed:
            return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status, allowed=allowed)

    # Apply updates
    changed = False
    if name is not None and name.strip() != r.get("name"):
        r["name"] = name.strip()
        r["normalized_name"] = _normalize_text(r["name"])
        if not r["normalized_name"]:
            return _err("VALIDATION_ERROR", "normalized_name must be non-empty (derived from name).")
        changed = True
    if cuisine is not None:
        r["cuisine"] = cuisine
        changed = True
    if tags is not None:
        r["tags"] = tags
        changed = True
    if city is not None:
        r["city"] = city
        changed = True
    if state is not None:
        r["state"] = state
        changed = True
    if country is not None:
        r["country"] = country
        changed = True
    if latitude is not None:
        r["latitude"] = float(latitude)
        changed = True
    if longitude is not None:
        r["longitude"] = float(longitude)
        changed = True
    if price_level is not None:
        r["price_level"] = int(price_level)
        changed = True
    if rating_avg is not None:
        r["rating_avg"] = float(rating_avg)
        changed = True
    if rating_count is not None:
        r["rating_count"] = int(rating_count)
        changed = True
    if status is not None:
        r["status"] = status
        changed = True

    # Enforce declared ranges post-update (business rule)
    # country enum
    if r.get("country") not in ("BR",):
        return _err("VALIDATION_ERROR", "country must be 'BR'.")
    # coordinates
    if r.get("latitude") is not None:
        try:
            lat = float(r.get("latitude"))
        except Exception:
            return _err("VALIDATION_ERROR", "latitude must be a number or null.")
        if lat < -90 or lat > 90:
            return _err("VALIDATION_ERROR", "latitude must be between -90 and 90.")
    if r.get("longitude") is not None:
        try:
            lon = float(r.get("longitude"))
        except Exception:
            return _err("VALIDATION_ERROR", "longitude must be a number or null.")
        if lon < -180 or lon > 180:
            return _err("VALIDATION_ERROR", "longitude must be between -180 and 180.")
    if r.get("price_level") is not None:
        if not isinstance(r.get("price_level"), int):
            return _err("VALIDATION_ERROR", "price_level must be an integer or null.")
        if r["price_level"] < 1 or r["price_level"] > 4:
            return _err("VALIDATION_ERROR", "price_level must be between 1 and 4.")
    if r.get("rating_avg") is not None:
        try:
            ravg = float(r.get("rating_avg"))
        except Exception:
            return _err("VALIDATION_ERROR", "rating_avg must be a number or null.")
        if ravg < 0 or ravg > 5:
            return _err("VALIDATION_ERROR", "rating_avg must be between 0 and 5.")
    if not isinstance(r.get("rating_count"), int) or r.get("rating_count") < 0:
        return _err("VALIDATION_ERROR", "rating_count must be an integer >= 0.")
    if not isinstance(r.get("tags"), list):
        return _err("VALIDATION_ERROR", "tags must be a non-null array.")

    # Must have effect
    if not changed:
        return _err("CONFLICT", "No fields changed; update would have no effect.")

    r["updated_at"] = _now_iso()
    restaurants[idx] = r
    _save("restaurants.json", restaurants)

    # Audit row into search_queries
    queries = _load("search_queries.json")
    latency_ms = int((time.time() - t0) * 1000)
    qry_id = "ifood_qry_" + now.strftime("%Y%m%d%H%M%S") + "_" + str(int(time.time() * 1000))[-6:]
    queries.append({
        "id": qry_id,
        "api_key_id": k.get("id"),
        "term": "__update_restaurant__:" + rid,
        "normalized_term": "__update_restaurant__:" + rid.lower(),
        "status": "completed",
        "result_count": 1,
        "error_code": None,
        "error_message": None,
        "client_ip": None,
        "user_agent": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
        "endpoint": "update_restaurant",
        "latency_ms": latency_ms,
    })
    _save("search_queries.json", queries)

    return {"restaurant": r}

def list_search_queries(api_key, status=None, api_key_id=None, term_contains=None, created_from=None, created_to=None, page=None, page_size=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0406000" if __import__("os").path.isdir("./environment_mix/0406000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1]
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _iso_day(dt):
        return dt.date().isoformat()

    def _hash_key(raw):
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _resolve_api_key(raw):
        if not isinstance(raw, str) or not raw:
            return None
        keys = _load("api_keys.json")
        h = _hash_key(raw)
        cands = []
        for k in keys:
            if k.get("id") == raw or k.get("key_prefix") == raw or k.get("key_hash") == h:
                cands.append(k)
        return (cands[0] if cands else None), keys

    def _reset_daily_if_needed(k, now):
        reset_at = _parse_dt(k.get("requests_today_reset_at"))
        if reset_at is None:
            k["requests_today"] = int(k.get("requests_today") or 0)
            k["requests_today_reset_at"] = now.replace(hour=0, minute=0, second=0, microsecond=0).isoformat() + "Z"
            return True
        if _iso_day(now) != _iso_day(reset_at):
            k["requests_today"] = 0
            k["requests_today_reset_at"] = now.replace(hour=0, minute=0, second=0, microsecond=0).isoformat() + "Z"
            return True
        return False

    def _count_last_minute_requests(key_id, now):
        queries = _load("search_queries.json")
        cutoff = now - datetime.timedelta(seconds=60)
        n = 0
        for q in queries:
            if q.get("api_key_id") != key_id:
                continue
            created = _parse_dt(q.get("created_at"))
            if created is None:
                continue
            if created >= cutoff:
                n += 1
        return n

    def _auth_and_limits():
        now = datetime.datetime.utcnow().replace(microsecond=0)
        k, all_keys = _resolve_api_key(api_key)
        if not k:
            return None, all_keys, _err("UNAUTHORIZED", "Missing or invalid API key.")
        if k.get("status") != "active":
            return None, all_keys, _err("UNAUTHORIZED", "API key is not active.", api_key_id=k.get("id"), status=k.get("status"))
        changed = _reset_daily_if_needed(k, now)

        rpm = k.get("requests_per_minute_limit")
        rpd = k.get("requests_per_day_limit")
        today = k.get("requests_today")
        if not isinstance(rpm, int) or rpm < 1:
            return None, all_keys, _err("VALIDATION_ERROR", "API key has invalid requests_per_minute_limit.", api_key_id=k.get("id"))
        if not isinstance(rpd, int) or rpd < 1:
            return None, all_keys, _err("VALIDATION_ERROR", "API key has invalid requests_per_day_limit.", api_key_id=k.get("id"))
        if not isinstance(today, int) or today < 0:
            return None, all_keys, _err("VALIDATION_ERROR", "API key has invalid requests_today.", api_key_id=k.get("id"))

        last_min = _count_last_minute_requests(k.get("id"), now)
        if last_min >= rpm:
            if changed:
                _save("api_keys.json", all_keys)
            return None, all_keys, _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rpm, used_last_minute=last_min, api_key_id=k.get("id"))

        if today >= rpd:
            if changed:
                _save("api_keys.json", all_keys)
            return None, all_keys, _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit_per_day=rpd, used_today=today, api_key_id=k.get("id"))

        k["requests_today"] = today + 1
        k["last_used_at"] = _now_iso()
        k["updated_at"] = _now_iso()
        _save("api_keys.json", all_keys)
        return k, all_keys, None

    # validate paging/sorting inputs
    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if sort_by is None:
        sort_by = "created_at"
    if sort_order is None:
        sort_order = "desc"

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "Field 'page' must be an integer >= 1.", field="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "Field 'page_size' must be an integer between 1 and 100.", field="page_size")
    if sort_by not in ("created_at", "updated_at"):
        return _err("VALIDATION_ERROR", "Field 'sort_by' must be one of: created_at, updated_at.", field="sort_by")
    if sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Field 'sort_order' must be one of: asc, desc.", field="sort_order")

    if status is not None and status not in ("received", "completed", "failed"):
        return _err("VALIDATION_ERROR", "Field 'status' must be one of: received, completed, failed.", field="status")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id):
        return _err("VALIDATION_ERROR", "Field 'api_key_id' must be a non-empty string.", field="api_key_id")
    if term_contains is not None and not isinstance(term_contains, str):
        return _err("VALIDATION_ERROR", "Field 'term_contains' must be a string.", field="term_contains")

    dt_from = None
    dt_to = None
    if created_from is not None:
        if not isinstance(created_from, str):
            return _err("VALIDATION_ERROR", "Field 'created_from' must be an RFC3339/ISO date-time string.", field="created_from")
        dt_from = _parse_dt(created_from)
        if dt_from is None:
            return _err("VALIDATION_ERROR", "Field 'created_from' could not be parsed as date-time.", field="created_from")
    if created_to is not None:
        if not isinstance(created_to, str):
            return _err("VALIDATION_ERROR", "Field 'created_to' must be an RFC3339/ISO date-time string.", field="created_to")
        dt_to = _parse_dt(created_to)
        if dt_to is None:
            return _err("VALIDATION_ERROR", "Field 'created_to' could not be parsed as date-time.", field="created_to")

    # auth + limits
    k, all_keys, e = _auth_and_limits()
    if e:
        return e

    queries = _load("search_queries.json")

    # filtering
    out = []
    term_sub = term_contains.lower() if isinstance(term_contains, str) else None
    for q in queries:
        if status is not None and q.get("status") != status:
            continue
        if api_key_id is not None and q.get("api_key_id") != api_key_id:
            continue
        if term_sub is not None:
            t = q.get("term") or ""
            if not isinstance(t, str) or term_sub not in t.lower():
                continue
        if dt_from is not None:
            c = _parse_dt(q.get("created_at"))
            if c is None or c < dt_from:
                continue
        if dt_to is not None:
            c = _parse_dt(q.get("created_at"))
            if c is None or c >= dt_to:
                continue
        out.append(q)

    # sorting
    def _key_fn(row):
        v = row.get(sort_by)
        dt = _parse_dt(v)
        return dt if dt is not None else datetime.datetime.min
    rev = (sort_order == "desc")
    out.sort(key=_key_fn, reverse=rev)

    total = len(out)
    start = (page - 1) * page_size
    end = start + page_size
    items = out[start:end]
    has_more = end < total

    return {
        "items": items,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "latency_ms": int((time.time() - t0) * 1000),
            "api_key_id": k.get("id")
        }
    }
